#include <stdio.h>
#include <stdlib.h>

#define MAX_N 200005
#define INF 1000000000

// Segment tree for range minimum update and point query
int seg[4 * MAX_N];
int lazy[4 * MAX_N];

void build(int node, int l, int r) {
    if (l == r) {
        seg[node] = INF;
        lazy[node] = 0;
        return;
    }
    int mid = (l + r) / 2;
    build(node * 2, l, mid);
    build(node * 2 + 1, mid + 1, r);
    seg[node] = INF;
    lazy[node] = 0;
}

void apply(int node, int val) {
    if (val < seg[node]) {
        seg[node] = val;
    }
    if (lazy[node] == 0 || val < lazy[node]) {
        lazy[node] = val;
    }
}

void push(int node) {
    if (lazy[node] != 0) {
        apply(node * 2, lazy[node]);
        apply(node * 2 + 1, lazy[node]);
        lazy[node] = 0;
    }
}

void update(int node, int l, int r, int ql, int qr, int val) {
    if (ql > r || qr < l) return;
    if (ql <= l && r <= qr) {
        apply(node, val);
        return;
    }
    push(node);
    int mid = (l + r) / 2;
    update(node * 2, l, mid, ql, qr, val);
    update(node * 2 + 1, mid + 1, r, ql, qr, val);
    seg[node] = (seg[node * 2] < seg[node * 2 + 1]) ? seg[node * 2] : seg[node * 2 + 1];
}

int query(int node, int l, int r, int pos) {
    if (l == r) {
        return seg[node];
    }
    push(node);
    int mid = (l + r) / 2;
    if (pos <= mid)
        return query(node * 2, l, mid, pos);
    else
        return query(node * 2 + 1, mid + 1, r, pos);
}

int main() {
    int H, W;
    scanf("%d %d", &H, &W);

    // Arrays to store blocked intervals per row
    int *A = (int*)malloc((H + 1) * sizeof(int));
    int *B = (int*)malloc((H + 1) * sizeof(int));
    for (int i = 1; i <= H; i++) {
        scanf("%d %d", &A[i], &B[i]);
    }

    // dp[j] = minimum moves to reach column j in current row
    // Initialize for row 1 (top row)
    int *dp = (int*)malloc((W + 2) * sizeof(int));
    for (int j = 1; j <= W; j++) {
        dp[j] = j - 1;  // moves to reach column j from column 1 (starting at column 1)
    }

    // Segment tree over columns for range updates
    build(1, 1, W);
    // Initialize segment tree with dp values
    for (int j = 1; j <= W; j++) {
        update(1, 1, W, j, j, dp[j]);
    }

    for (int i = 1; i <= H; i++) {
        int L = A[i], R = B[i];

        // Query the minimum value in the blocked range
        // We need to find min over columns that can move down to this row
        // The allowed columns are those not in [L, R] that have a path from above.
        // For columns in [L, R], we cannot move down from them.
        // So we need to compute new dp for next row.

        // New array for next row
        int *ndp = (int*)malloc((W + 2) * sizeof(int));
        for (int j = 1; j <= W; j++) ndp[j] = INF;

        // For columns before L: they can move down directly or come from left
        // We can compute using segment tree queries for minimum in allowed ranges.

        // First, find the best value to come into column j from above (if j not blocked)
        // For j from 1 to L-1, we can come from above directly from column j
        // or from left. We'll compute using a sweep.

        // Use a variable 'best' that tracks the minimum dp value in allowed columns
        // that can reach current column by moving right.

        int best = INF;
        // Sweep from left to right
        for (int j = 1; j <= W; j++) {
            // Update best with dp value of current column if it's allowed to move down
            if (j < L || j > R) {
                // Column j is allowed to move down
                int val = query(1, 1, W, j);
                if (val < best) best = val;
            }
            // Now compute ndp[j]
            // We can reach column j in next row either by:
            // 1. Moving down from same column j (if allowed) => dp[j] + 1
            // 2. Moving right from previous column in next row => ndp[j-1] + 1
            // But we also need to consider coming from left in the same row before moving down?
            // Actually the movement is: from start to some column in top row, then repeatedly 
            // move right or down. So to reach (i+1, j), we either:
            // - come from (i, j) by moving down: cost = dp[j] + 1
            // - come from (i+1, j-1) by moving right: cost = ndp[j-1] + 1
            // So we can compute ndp[j] = min(dp[j] + 1 if allowed, ndp[j-1] + 1)

            int cand1 = INF;
            if (j < L || j > R) {
                cand1 = query(1, 1, W, j) + 1;
            }
            int cand2 = (j > 1) ? (ndp[j-1] + 1) : INF;
            ndp[j] = (cand1 < cand2) ? cand1 : cand2;
        }

        // Also consider coming from right? No, only right moves allowed, so left to right sweep is sufficient.

        // Update segment tree with new dp values
        for (int j = 1; j <= W; j++) {
            update(1, 1, W, j, j, ndp[j]);
        }

        // Find answer for this row: minimum ndp over all columns
        int ans = INF;
        for (int j = 1; j <= W; j++) {
            if (ndp[j] < ans) ans = ndp[j];
        }
        if (ans >= INF) printf("-1\n");
        else printf("%d\n", ans);

        // Free old dp and set new
        free(dp);
        dp = ndp;
    }

    free(dp);
    free(A);
    free(B);
    return 0;
}

