typedef long long ll;

typedef struct Node {
    int key;            // current column
    ll val;             // original starting column
    int pri;
    struct Node *l, *r;
} Node;

static unsigned int rng_state = 2463534242u;
static unsigned int xrnd() {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

static Node* new_node(int key, ll val) {
    Node* t = (Node*)malloc(sizeof(Node));
    t->key = key;
    t->val = val;
    t->pri = (int)xrnd();
    t->l = t->r = NULL;
    return t;
}

static void split(Node* t, int key, Node** a, Node** b) {
    if (!t) {
        *a = *b = NULL;
    } else if (t->key < key) {
        split(t->r, key, &t->r, b);
        *a = t;
    } else {
        split(t->l, key, a, &t->l);
        *b = t;
    }
}

static Node* merge(Node* a, Node* b) {
    if (!a) return b;
    if (!b) return a;
    if (a->pri > b->pri) {
        a->r = merge(a->r, b);
        return a;
    } else {
        b->l = merge(a, b->l);
        return b;
    }
}

static Node* insert_node(Node* t, Node* it) {
    if (!t) return it;
    if (it->pri > t->pri) {
        split(t, it->key, &it->l, &it->r);
        return it;
    }
    if (it->key < t->key) t->l = insert_node(t->l, it);
    else t->r = insert_node(t->r, it);
    return t;
}

static Node* erase_key(Node* t, int key) {
    if (!t) return NULL;
    if (t->key == key) {
        Node* res = merge(t->l, t->r);
        free(t);
        return res;
    }
    if (key < t->key) t->l = erase_key(t->l, key);
    else t->r = erase_key(t->r, key);
    return t;
}

static Node* get_min(Node* t) {
    if (!t) return NULL;
    while (t->l) t = t->l;
    return t;
}

static Node* get_max(Node* t) {
    if (!t) return NULL;
    while (t->r) t = t->r;
    return t;
}

static Node* lower_bound(Node* t, int key) {
    Node* ans = NULL;
    while (t) {
        if (t->key >= key) {
            ans = t;
            t = t->l;
        } else {
            t = t->r;
        }
    }
    return ans;
}

static void free_tree(Node* t) {
    if (!t) return;
    free_tree(t->l);
    free_tree(t->r);
    free(t);
}

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    int *A = (int*)malloc((H + 1) * sizeof(int));
    int *B = (int*)malloc((H + 1) * sizeof(int));
    for (int i = 1; i <= H; i++) scanf("%d %d", &A[i], &B[i]);

    Node* root = NULL;

    // Initially, every top-row column j is reachable with starting column j.
    for (int j = 1; j <= W; j++) {
        root = insert_node(root, new_node(j, j));
    }

    for (int i = 1; i <= H; i++) {
        int l = A[i], r = B[i];

        Node *x, *y, *z;
        split(root, l, &x, &y);
        split(y, r + 1, &y, &z);   // y contains keys in [l, r]

        ll best_start = -1;
        if (y) {
            Node* mx = get_max(y);
            best_start = mx->val;
        }

        free_tree(y);
        root = merge(x, z);

        // Move the rightmost removed reachable state to r+1 if possible and empty.
        if (best_start != -1 && r + 1 <= W) {
            Node* ex = lower_bound(root, r + 1);
            if (!ex || ex->key != r + 1) {
                root = insert_node(root, new_node(r + 1, best_start));
            }
        }

        if (!root) {
            printf("-1\n");
        } else {
            Node* mn = get_min(root);
            ll ans = (ll)i + (ll)mn->key - mn->val;
            printf("%lld\n", ans);
        }
    }

    free_tree(root);
    free(A);
    free(B);
    return 0;
}

