public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int H = Integer.parseInt(st.nextToken());
        int W = Integer.parseInt(st.nextToken());

        // Store blocked intervals per row
        int[][] blocked = new int[H][2];
        for (int i = 0; i < H; i++) {
            st = new StringTokenizer(br.readLine());
            blocked[i][0] = Integer.parseInt(st.nextToken()) - 1; // 0-based
            blocked[i][1] = Integer.parseInt(st.nextToken()) - 1;
        }

        // We'll keep the minimum column we can be at in the current row
        // Initially, we can start at any column in row 0 (top row)
        // We'll simulate row by row.
        int minCol = 0; // smallest column reachable in current row
        // If minCol > W-1, unreachable
        StringBuilder sb = new StringBuilder();

        for (int row = 0; row < H; row++) {
            int L = blocked[row][0];
            int R = blocked[row][1];

            // If minCol is inside the blocked interval, we need to move right past it
            if (minCol >= L && minCol <= R) {
                minCol = R + 1;
            }
            // If minCol is already beyond W, unreachable for this and all later rows
            if (minCol >= W) {
                for (int r = row; r < H; r++) {
                    sb.append("-1\n");
                }
                System.out.print(sb);
                return;
            }
            // Moves to reach current row: (row+1) down moves + minCol right moves
            sb.append((row + 1 + minCol)).append("\n");
        }

        System.out.print(sb);
    }
}

