public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int H = Integer.parseInt(st.nextToken());
        int W = Integer.parseInt(st.nextToken());
        int[] A = new int[H+1], B = new int[H+1];
        for (int i = 1; i <= H; i++) {
            st = new StringTokenizer(br.readLine());
            A[i] = Integer.parseInt(st.nextToken());
            B[i] = Integer.parseInt(st.nextToken());
        }
        int INF = Integer.MAX_VALUE/2;
        int[] best = new int[W+2]; // best[c] = min start col to reach col c in current row
        for (int c = 1; c <= W; c++) best[c] = c; // row 1, start anywhere
        StringBuilder sb = new StringBuilder();
        for (int k = 1; k <= H; k++) {
            // Compute prefix min of best over allowed columns in row k
            int[] newBest = new int[W+2];
            Arrays.fill(newBest, INF);
            int prefMin = INF;
            for (int c = 1; c <= W; c++) {
                if (c < A[k] || c > B[k]) { // allowed to move down from c in row k
                    if (best[c] < INF) prefMin = Math.min(prefMin, best[c]);
                }
                if (c < A[k] || c > B[k]) newBest[c] = prefMin; // can reach row k+1 at col c
                // Actually newBest[c] = min start to reach col c in row k+1
            }
            // answer for k
            int ans = INF;
            for (int c = 1; c <= W; c++) if (newBest[c] < INF) ans = Math.min(ans, c - newBest[c]);
            sb.append(ans == INF ? -1 : ans + k).append('\n');
            best = newBest;
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int H = fs.nextInt();
        int W = fs.nextInt();

        int[] A = new int[H + 1];
        int[] B = new int[H + 1];
        for (int i = 1; i <= H; i++) {
            A[i] = fs.nextInt();
            B[i] = fs.nextInt();
        }

        // For each currently reachable column x (1-indexed), store its extra right moves:
        // cost = currentColumn - x
        // total moves to be at current row = rowIndex + cost
        TreeMap<Integer, Integer> map = new TreeMap<>();
        TreeMap<Integer, Integer> multiset = new TreeMap<>();

        for (int x = 1; x <= W; x++) {
            map.put(x, 0);
            add(multiset, 0);
        }

        StringBuilder sb = new StringBuilder();

        for (int i = 1; i <= H; i++) {
            int l = A[i];
            int r = B[i];

            Integer start = map.ceilingKey(l);
            List<int[]> removed = new ArrayList<>();

            while (start != null && start <= r) {
                int cost = map.remove(start);
                removed.add(new int[]{start, cost});
                remove(multiset, cost);
                start = map.ceilingKey(l);
            }

            if (!removed.isEmpty() && r + 1 <= W) {
                int best = Integer.MAX_VALUE;
                for (int[] p : removed) {
                    int x = p[0];
                    int cost = p[1];
                    best = Math.min(best, cost + (r + 1 - x));
                }

                Integer existing = map.get(r + 1);
                if (existing == null || best < existing) {
                    if (existing != null) remove(multiset, existing);
                    map.put(r + 1, best);
                    add(multiset, best);
                }
            }

            if (multiset.isEmpty()) {
                sb.append(-1).append('\n');
            } else {
                sb.append(i + multiset.firstKey()).append('\n');
            }
        }

        System.out.print(sb.toString());
    }

    static void add(TreeMap<Integer, Integer> ms, int x) {
        ms.put(x, ms.getOrDefault(x, 0) + 1);
    }

    static void remove(TreeMap<Integer, Integer> ms, int x) {
        int c = ms.get(x);
        if (c == 1) ms.remove(x);
        else ms.put(x, c - 1);
    }
}

