using namespace std;
int main(){
    int H, W;
    cin >> H >> W;
    vector<int> A(H+1), B(H+1);
    for(int i=1;i<=H;i++) cin>>A[i]>>B[i];
    // dp[c] = min right moves to be at column c (= c - best_start_col)
    // Represent as: for column c, min_cost = c - max_start where max_start is max starting col reachable to c
    // Use array of size W+1
    vector<int> dp(W+2, INT_MAX);
    for(int c=1;c<=W;c++) dp[c]=0; // start anywhere, cost = 0
    for(int k=1;k<=H;k++){
        // Move down from row k: blocked at [A[k], B[k]]
        // First, propagate right moves within row k (already done via prefix min of dp)
        // Apply right-propagation: dp[c] = min(dp[c], dp[c-1]) -- already inherent
        // Actually dp represents after entering row k
        // Propagate rightward
        for(int c=2;c<=W;c++) if(dp[c-1]!=INT_MAX) dp[c]=min(dp[c],dp[c-1]);
        // Now move down: blocked columns [A[k],B[k]] cannot move down
        vector<int> ndp(W+2, INT_MAX);
        for(int c=1;c<=W;c++){
            if(c>=A[k]&&c<=B[k]) continue;
            ndp[c]=dp[c];
        }
        // Find min in ndp
        int ans=INT_MAX;
        for(int c=1;c<=W;c++) if(ndp[c]!=INT_MAX) ans=min(ans,ndp[c]);
        cout<<(ans==INT_MAX?-1:k+ans)<<"\n";
        dp=ndp;
    }
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<int> A(H + 1), B(H + 1);
    for (int i = 1; i <= H; i++) cin >> A[i] >> B[i];

    const long long INF = (1LL << 60);

    // active positions are stored by current column x (1..W)
    // value = minimum starting column s among paths that currently end at x
    // then moves to current row = (row-1) + (x-s)
    map<int, int> mp;
    multiset<int> vals; // stores x - s for active states

    for (int x = 1; x <= W; x++) {
        mp[x] = x;
        vals.insert(0); // x - s = 0 initially
    }

    for (int i = 1; i <= H; i++) {
        int L = A[i], R = B[i];

        auto itL = mp.lower_bound(L);
        auto itR = mp.upper_bound(R);

        vector<pair<int,int>> removed;
        int minStart = INT_MAX;

        for (auto it = itL; it != itR; ++it) {
            int x = it->first;
            int s = it->second;
            removed.push_back(*it);
            minStart = min(minStart, s);
            auto vit = vals.find(x - s);
            if (vit != vals.end()) vals.erase(vit);
        }

        for (auto &p : removed) mp.erase(p.first);

        // states in [L, R] cannot go down; they may move right to R+1
        if (minStart != INT_MAX && R + 1 <= W) {
            auto it = mp.find(R + 1);
            if (it == mp.end() || minStart < it->second) {
                if (it != mp.end()) {
                    auto vit = vals.find((R + 1) - it->second);
                    if (vit != vals.end()) vals.erase(vit);
                }
                mp[R + 1] = minStart;
                vals.insert((R + 1) - minStart);
            }
        }

        if (vals.empty()) {
            cout << -1 << '\n';
        } else {
            long long ans = i + (long long)(*vals.begin());
            cout << ans << '\n';
        }
    }

    return 0;
}
